import sys


def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    queries = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(q)]
    MOD = 1_000_000_007
    max_r = max(r for r, _ in queries)
    max_c = max(c for _, c in queries)
    wanted = {}
    for r, c in queries:
        wanted.setdefault(r, set()).add(c)
    found = {}
    row = [1] * (max_c + 1)
    for r in range(max_r + 1):
        if r > 0:
            new_row = [0] * (max_c + 1)
            for c in range(max_c + 1):
                ways = row[c]
                if c > 0:
                    ways += new_row[c - 1]
                new_row[c] = ways % MOD
            row = new_row
        for c in wanted.get(r, ()):
            found[(r, c)] = row[c]
    print("\n".join(str(found[(r, c)]) for r, c in queries))


main()
